/bin/zsh -lc "node acceptance.mjs .
node --check app.mjs
node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
const root=process.cwd();
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'cafe-focused-'));
const call=(args)=>spawnSync(process.execPath,[path.join(root,'app.mjs'),...args],{encoding:'utf8'});
try {
  const file=path.join(dir,'jobs.json');
  let r=call([file,'add',JSON.stringify({id:'job-u',title:'  🔧  '})]);
  assert.equal(r.status,0); assert.deepEqual(JSON.parse(r.stdout),{id:'job-u',title:'🔧',status:'open'});
  const before=fs.readFileSync(file);
  r=call([file,'list','extra']); assert.notEqual(r.status,0); assert.equal(r.stdout,''); assert.deepEqual(JSON.parse(r.stderr),{error:'invalid-input'}); assert.deepEqual(fs.readFileSync(file),before);
  fs.writeFileSync(file,JSON.stringify({version:1,jobs:[{id:'job-a',title:' Lamp ',status:'open',extra:true}]}));
  const corrupt=fs.readFileSync(file);
  r=call([file,'list']); assert.deepEqual(JSON.parse(r.stderr),{error:'invalid-data'}); assert.deepEqual(fs.readFileSync(file),corrupt);
  r=call([dir,'list']); assert.deepEqual(JSON.parse(r.stderr),{error:'storage-error'}); assert.equal(r.stdout,'');
  console.log(JSON.stringify({focused:'passed',cases:4}));
} finally { fs.rmSync(dir,{recursive:true,force:true}); }
EOF"
